type ScannedReceipt = any; // vendored: was `import type` from './api'
type UserProfile = any; // vendored: was `import type` from './firestoreUserProfile'

export type ReceiptOriginSummary = {
  /** Someone else entered it and shared it with you. */
  isSharedWithCurrentUser: boolean;
  /**
   * YOU entered it — scanned, emailed, manual, Clover, tapped — AND it is out
   * to a group or to other people.
   *
   * The two flags are mutually exclusive by construction, and together they
   * split receipts three ways rather than two: yours and private, yours and
   * shared out, or someone else's shared in. The middle case was always
   * derivable (the `detail` line has said "Scanned by you • Family" for as
   * long as this function has existed) but nothing surfaced it as a flag, so
   * no list could style it.
   */
  isSharedByCurrentUser: boolean;
  title: string;
  detail: string;
};

export function getReceiptGroupIds(receipt: Pick<ScannedReceipt, 'familyGroupId' | 'sharedGroupIds'>): string[] {
  const ids = new Set<string>();
  if (receipt.familyGroupId) ids.add(receipt.familyGroupId);
  (receipt.sharedGroupIds ?? []).forEach((id) => {
    if (id) ids.add(id);
  });
  return Array.from(ids);
}

export function isReceiptSharedWithCurrentUser(
  receipt: Pick<ScannedReceipt, 'userId' | 'sharedWith'>,
  currentUserId?: string | null
): boolean {
  if (!currentUserId) return false;
  return receipt.userId !== currentUserId && (receipt.sharedWith ?? []).includes(currentUserId);
}

export function getUserProfileDisplayName(profile?: UserProfile | null, fallback = 'PapeX user'): string {
  if (!profile) return fallback;
  const fullName = `${profile.firstName ?? ''} ${profile.lastName ?? ''}`.trim();
  return (
    profile.displayName?.trim() ||
    profile.preferredName?.trim() ||
    fullName ||
    profile.email?.split('@')[0]?.trim() ||
    fallback
  );
}

export function getReceiptSourceLabel(source: ScannedReceipt['source']): string {
  switch (source) {
    case 'email':
      return 'Email';
    case 'manual':
      return 'Manual';
    case 'clover':
      return 'Clover';
    case 'rdh':
      // Tap-to-receipt via an RDH device. Without this case these fell through to
      // 'Scanned' on both the list and the detail screen.
      return 'Tapped';
    case 'scanned':
    default:
      return 'Scanned';
  }
}

/**
 * Semantic `AppIcon` name for a receipt's provenance glyph.
 *
 * Keyed on `source`, NOT on the display label. Both receipt lists used to pick
 * this with an inline ternary over `originTitle` — which meant `source: 'rdh'`
 * (title `'Tapped'`) matched no branch and fell through to the scanned icon,
 * and any copy change to a label would silently break the glyph the same way.
 *
 * `rdh` deliberately still returns `'scan'`: there is no `contactless`/`nfc`
 * glyph in the icon font, and adding one means regenerating the subset (see
 * scripts/icons/build-material-font.mjs). It is now a stated choice in one
 * place rather than an accident in two.
 *
 * Return type is a literal union rather than `AppIconName` so this service
 * doesn't reach up into components/ — every member is a valid `AppIconName`.
 */
export function getReceiptSourceIconName(
  source: ScannedReceipt['source'],
  isSharedWithCurrentUser: boolean,
  isSharedByCurrentUser = false
): 'people' | 'share' | 'mail' | 'edit' | 'card' | 'scan' {
  // Shared-in wins over the source: what matters first is that it isn't yours.
  if (isSharedWithCurrentUser) return 'people';
  // Shared-out is the next most important thing about a receipt you DO own —
  // the source is still true, but "other people can see this" is what changes
  // how you treat it. Distinct from the shared-in glyph on purpose: `people`
  // means someone gave it to you, `share` means you gave it away.
  if (isSharedByCurrentUser) return 'share';
  switch (source) {
    case 'email':
      return 'mail';
    case 'manual':
      return 'edit';
    case 'clover':
      return 'card';
    case 'rdh':
    case 'scanned':
    default:
      return 'scan';
  }
}

export function buildReceiptOriginSummary(
  receipt: ScannedReceipt,
  currentUserId: string | null | undefined,
  groupNameById: Map<string, string>,
  ownerNameById: Map<string, string>
): ReceiptOriginSummary {
  const groupLabels = getReceiptGroupIds(receipt).map((id) => groupNameById.get(id) ?? 'Group');
  const groupText = groupLabels.length > 0 ? groupLabels.join(', ') : 'a group';
  const sharedWithCurrentUser = isReceiptSharedWithCurrentUser(receipt, currentUserId);

  if (sharedWithCurrentUser) {
    const ownerName = ownerNameById.get(receipt.userId) ?? 'PapeX user';
    return {
      isSharedWithCurrentUser: true,
      isSharedByCurrentUser: false,
      title: 'Shared',
      /* "in a group" ONLY WHEN THERE IS ONE. `groupText` falls back to the
         words "a group", which on a person-to-person share — the sharing
         centre's whole incoming tab — is a claim about a group that does not
         exist. Fixed 2026-08-17; the prefix stays "Shared by" either way,
         which is what the receipt card keys its blue tint on. */
      detail: groupLabels.length > 0
        ? `Shared by ${ownerName} in ${groupText}`
        : `Shared by ${ownerName}`,
    };
  }

  // Ownership is checked explicitly rather than inferred from "not shared with
  // me". Without a currentUserId — or on a receipt that is genuinely someone
  // else's but not shared to you — falling through to "you shared this" would
  // be a claim about authorship, and a wrong one.
  const isOwn = !!currentUserId && receipt.userId === currentUserId;

  /* SOMEBODY ELSE'S RECEIPT THAT YOU CAN NEVERTHELESS SEE — you are looking at
     it through a GROUP.

     `sharedWith` is the person-to-person list and carries no group membership,
     so `isReceiptSharedWithCurrentUser` is false for a receipt a fellow member
     put into a shared group. Until 2026-08-17 that fell through to the line
     below and read "Scanned by you", which is a claim about authorship and a
     wrong one — the exact case the comment above already called out but did not
     handle. It only became visible when the group screens started rendering
     this line at all (familySettings' "Recent receipts"), and it is precisely
     what Nico asked those rows to say: shared, and by whom.

     Guarded on knowing BOTH ids. Without them the source-only line below is
     still the honest answer, so nothing about a signed-out or id-less render
     changes. */
  if (currentUserId && receipt.userId && !isOwn) {
    const ownerName = ownerNameById.get(receipt.userId) ?? 'PapeX user';
    return {
      isSharedWithCurrentUser: true,
      isSharedByCurrentUser: false,
      title: 'Shared',
      detail: groupLabels.length > 0
        ? `Shared by ${ownerName} in ${groupText}`
        : `Shared by ${ownerName}`,
    };
  }
  const sharedOutByCurrentUser =
    isOwn && (groupLabels.length > 0 || (receipt.sharedWith ?? []).length > 0);

  const sourceLabel = getReceiptSourceLabel(receipt.source ?? 'scanned');
  return {
    isSharedWithCurrentUser: false,
    isSharedByCurrentUser: sharedOutByCurrentUser,
    title: sourceLabel,
    detail: groupLabels.length > 0 ? `${sourceLabel} by you • ${groupText}` : `${sourceLabel} by you`,
  };
}
